messages.content:
Proceed with KPP-001 — Knowledge Preservation Compiler Framework.
Create contracts first, no Git/conversation compiler yet.
Bashmkdir -p apps/lumina-runtime/src/knowledge-preservation/{evidence,ir,compiler}

cat > apps/lumina-runtime/src/knowledge-preservation/evidence/EvidenceItem.ts <<'EOF'
export type EvidenceType =
  | "conversation"
  | "commit"
  | "tag"
  | "branch"
  | "ADR"
  | "RFC"
  | "document"
  | "source-file"
  | "runtime-event"
  | "engineering-execution"
  | "issue"
  | "pull-request"
  | "specification"
  | "roadmap"
  | "milestone"
  | "build-output"
  | "incident-log";

export interface EvidenceItem {
  id: string;
  type: EvidenceType;
  title: string;
  source: string;
  capturedAt: number;
  observedAt: number;
  contentRef: string;
  checksum?: string;
  metadata: Record<string, unknown>;
  relationships: Record<string, string[]>;
}
EOF

cat > apps/lumina-runtime/src/knowledge-preservation/evidence/index.ts <<'EOF'
export * from "./EvidenceItem.js";
EOF

cat > apps/lumina-runtime/src/knowledge-preservation/ir/KnowledgeIRItem.ts <<'EOF'
import type {
  EvidenceType,
} from "../evidence/index.js";

export type KnowledgeIRCandidateType =
  | "CandidateCapability"
  | "CandidateDecision"
  | "CandidatePrinciple"
  | "CandidateLesson"
  | "CandidateIncident"
  | "CandidateRecovery"
  | "CandidateComponent"
  | "CandidateSubsystem"
  | "CandidateMilestone"
  | "CandidateRoadmap"
  | "CandidateExecution"
  | "CandidateArtifact"
  | "CandidateRelationship";

export type KnowledgeIRStatus =
  | "extracted"
  | "normalized"
  | "needs-review"
  | "approved"
  | "rejected"
  | "merged"
  | "superseded";

export interface KnowledgeIRCompilerMetadata {
  compilerName: string;
  compilerVersion: string;
  evidenceSourceType: EvidenceType;
  extractedAt: number;
  extractionMethod: string;
  confidenceBasis: string;
}

export interface KnowledgeIRItem {
  id: string;
  candidateType: KnowledgeIRCandidateType;
  title: string;
  summary: string;
  confidence: number;
  evidenceRefs: string[];
  proposedRelationships: Record<string, string[]>;
  extractedAt: number;
  compiler: KnowledgeIRCompilerMetadata;
  status: KnowledgeIRStatus;
  metadata: Record<string, unknown>;
}
EOF

cat > apps/lumina-runtime/src/knowledge-preservation/ir/index.ts <<'EOF'
export * from "./KnowledgeIRItem.js";
EOF

cat > apps/lumina-runtime/src/knowledge-preservation/compiler/KnowledgeCompiler.ts <<'EOF'
import type {
  EvidenceItem,
} from "../evidence/index.js";

import type {
  KnowledgeIRItem,
} from "../ir/index.js";

export interface KnowledgeCompiler {
  readonly name: string;
  readonly version: string;

  supports(
    evidence: EvidenceItem,
  ): boolean;

  compile(
    evidence: EvidenceItem,
  ): Promise<KnowledgeIRItem[]>;
}
EOF

cat > apps/lumina-runtime/src/knowledge-preservation/compiler/index.ts <<'EOF'
export * from "./KnowledgeCompiler.js";
EOF

cat > apps/lumina-runtime/src/knowledge-preservation/index.ts <<'EOF'
export * from "./evidence/index.js";
export * from "./ir/index.js";
export * from "./compiler/index.js";
EOF

npm --workspace packages/platform-sdk run build
npm --workspace apps/lumina-runtime run build
npm --workspace apps/lumina-builder run build
If green:
Bashgit add .

git commit -m "feat(knowledge): add preservation compiler framework"

git tag kpp-001-compiler-framework-green

git push

git push origin kpp-001-compiler-framework-green
